CREATE TABLE IF NOT EXISTS `shopex` (
  `vnum` int(11) NOT NULL DEFAULT 0,
  `name` varchar(32) NOT NULL DEFAULT 'Noname',
  `npc_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `level_min` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`vnum`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `shopex_item` (
  `shop_vnum` int(11) NOT NULL DEFAULT 0,
  `pos` smallint(6) NOT NULL DEFAULT 0,
  `item_vnum` int(11) NOT NULL DEFAULT 0,
  `count` smallint(4) unsigned NOT NULL DEFAULT 1,
  `price` bigint(16) unsigned NOT NULL DEFAULT 0,
  `price_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `price_type` enum('GOLD','COINS','ITEM','EXP') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'GOLD',
  `socket0` int(10) unsigned NOT NULL DEFAULT 0,
  `socket1` int(10) unsigned NOT NULL DEFAULT 0,
  `socket2` int(10) unsigned NOT NULL DEFAULT 0,
  `attrtype0` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue0` smallint(6) NOT NULL DEFAULT 0,
  `attrtype1` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue1` smallint(6) NOT NULL DEFAULT 0,
  `attrtype2` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue2` smallint(6) NOT NULL DEFAULT 0,
  `attrtype3` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue3` smallint(6) NOT NULL DEFAULT 0,
  `attrtype4` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue4` smallint(6) NOT NULL DEFAULT 0,
  `attrtype5` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue5` smallint(6) NOT NULL DEFAULT 0,
  `attrtype6` tinyint(4) NOT NULL DEFAULT 0,
  `attrvalue6` smallint(6) NOT NULL DEFAULT 0,
  `extra1_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `extra1_count` int(10) unsigned NOT NULL DEFAULT 0,
  `extra2_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `extra2_count` int(10) unsigned NOT NULL DEFAULT 0,
  `extra3_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `extra3_count` int(10) unsigned NOT NULL DEFAULT 0,
  `extra4_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `extra4_count` int(10) unsigned NOT NULL DEFAULT 0,
  `extra5_vnum` int(10) unsigned NOT NULL DEFAULT 0,
  `extra5_count` int(10) unsigned NOT NULL DEFAULT 0,
  UNIQUE KEY `vnum_unique` (`shop_vnum`,`pos`,`item_vnum`,`count`,`price`,`price_vnum`,`price_type`,`extra1_vnum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=FIXED;


-- Anka sekmeli NPC magazalari (silahci, zirhci, kuyumcu, demirci, genel magaza, simyaci vb.)
-- Kendi magazalarin varsa once yedek al; tablo icerigi silinip yeniden yazilir.
DELETE FROM `shopex_item`;
DELETE FROM `shopex`;
